use crate::encounter_store;
use std::{fs, path::{Path, PathBuf}};

const ARCHIVE_FILE: &str = "index.html";

pub fn generate(root: &Path) -> Result<PathBuf, String> {
    let dir = encounter_store::dir(root);
    fs::create_dir_all(&dir).map_err(|e| format!("create encounter history folder: {e}"))?;
    let records = encounter_store::load_recent(root, encounter_store::DEFAULT_LIMIT);
    let mut json = serde_json::to_string(&records).map_err(|e| format!("serialize encounter history: {e}"))?;
    // A JSON literal is embedded into an inline script. Escape characters that
    // could otherwise terminate a script element if a player/boss name contains
    // unusual text.
    json = json.replace('&', "\\u0026").replace('<', "\\u003c").replace('>', "\\u003e");

    let mut html = String::with_capacity(json.len().saturating_add(24_000));
    html.push_str(HTML_HEAD);
    html.push_str(&json);
    html.push_str(HTML_TAIL);

    let target = dir.join(ARCHIVE_FILE);
    let pending = dir.join("index.html.new");
    fs::write(&pending, html.as_bytes()).map_err(|e| format!("write encounter history: {e}"))?;
    if target.exists() {
        fs::remove_file(&target).map_err(|e| format!("replace old encounter history: {e}"))?;
    }
    fs::rename(&pending, &target).map_err(|e| format!("install encounter history: {e}"))?;
    Ok(target)
}

const HTML_HEAD: &str = r#"<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<meta http-equiv="Content-Security-Policy" content="default-src 'none'; img-src data:; style-src 'unsafe-inline'; script-src 'unsafe-inline'; connect-src 'none'; object-src 'none'; base-uri 'none'; form-action 'none'">
<title>BPSR ReadyAlert Encounter History</title>
<style>
:root{color-scheme:dark;--bg:#0e1116;--panel:#151a21;--panel2:#1b222b;--line:#29323d;--text:#e8edf3;--muted:#8793a3;--accent:#65c9ff;--good:#75d49b;--warn:#f0c55f;--danger:#f07878;--hover:#202833}
*{box-sizing:border-box}[hidden]{display:none!important}html,body{margin:0;min-height:100%;background:var(--bg);color:var(--text);font:14px/1.45 "Segoe UI",system-ui,-apple-system,sans-serif}button,input,select{font:inherit;color:inherit}.shell{display:grid;grid-template-columns:340px minmax(0,1fr);min-height:100vh}.left{position:sticky;top:0;height:100vh;border-right:1px solid var(--line);background:#11161c;display:flex;flex-direction:column}.brand{padding:18px 18px 13px;border-bottom:1px solid var(--line)}.brand h1{font-size:16px;margin:0}.brand p{font-size:12px;color:var(--muted);margin:3px 0 0}.local{color:#9ed9af;margin-top:8px;font-size:11px}.search-wrap{padding:12px;border-bottom:1px solid var(--line)}.search{width:100%;height:36px;border-radius:7px;border:1px solid #343e4a;background:var(--panel);padding:0 10px;outline:none}.search:focus{border-color:#4e94ba;box-shadow:0 0 0 2px rgba(101,201,255,.12)}.enc-list{overflow:auto;padding:8px;flex:1}.enc-card{width:100%;border:1px solid transparent;background:transparent;border-radius:8px;padding:10px;text-align:left;cursor:pointer;margin-bottom:3px}.enc-card:hover{background:var(--hover)}.enc-card.active{background:#1e2a35;border-color:#30485b}.enc-title{font-weight:650;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.enc-meta{display:flex;gap:7px;flex-wrap:wrap;color:var(--muted);font-size:11px;margin-top:4px}.enc-stat{display:flex;justify-content:space-between;margin-top:7px;font-size:12px;color:#b9c3cf}.main{min-width:0}.top{position:sticky;top:0;z-index:10;background:rgba(14,17,22,.96);backdrop-filter:blur(12px);border-bottom:1px solid var(--line);padding:17px 22px}.title-row{display:flex;justify-content:space-between;gap:18px;align-items:flex-start}.top h2{font-size:20px;margin:0}.subtitle{color:var(--muted);font-size:12px;margin-top:4px}.pills{display:flex;gap:6px;flex-wrap:wrap;justify-content:flex-end}.pill{border:1px solid #34404d;border-radius:999px;padding:4px 8px;color:#b8c4d0;font-size:11px;background:#171d25}.content{max-width:1220px;margin:0 auto;padding:18px 22px 60px}.hero{display:grid;grid-template-columns:repeat(5,minmax(120px,1fr));gap:10px;margin-bottom:16px}.metric{background:var(--panel);border:1px solid var(--line);border-radius:9px;padding:12px}.metric .k{font-size:11px;text-transform:uppercase;letter-spacing:.06em;color:var(--muted)}.metric .v{font-size:20px;font-weight:700;margin-top:2px;font-variant-numeric:tabular-nums}.layout{display:grid;grid-template-columns:260px minmax(0,1fr);gap:14px}.players,.detail{background:var(--panel);border:1px solid var(--line);border-radius:9px;overflow:hidden}.section-head{padding:11px 13px;border-bottom:1px solid var(--line);font-size:12px;font-weight:700;color:#cbd4de}.player-list{padding:6px}.player{width:100%;border:0;background:transparent;text-align:left;border-radius:7px;padding:9px 10px;cursor:pointer}.player:hover{background:var(--hover)}.player.active{background:#202d38}.player-name{font-weight:650;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.player-sub{color:var(--muted);font-size:11px;margin-top:2px}.tabs{display:flex;gap:2px;padding:7px 8px;border-bottom:1px solid var(--line);overflow:auto}.tab{border:0;background:transparent;padding:7px 9px;border-radius:6px;cursor:pointer;color:#aeb9c5;white-space:nowrap;font-size:12px}.tab:hover{background:var(--hover)}.tab.active{background:#253441;color:#fff}.pane{padding:13px}.grid2{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:9px}.mini{background:var(--panel2);border:1px solid #29333f;border-radius:8px;padding:10px}.mini .label{color:var(--muted);font-size:11px}.mini .value{font-size:16px;font-weight:650;margin-top:2px}.table-wrap{overflow:auto;border:1px solid var(--line);border-radius:8px}.table{width:100%;border-collapse:collapse;min-width:650px}.table th,.table td{padding:8px 10px;border-bottom:1px solid #27303a;text-align:right;font-variant-numeric:tabular-nums}.table th{position:sticky;top:0;background:#192028;color:#8f9bab;font-size:10px;text-transform:uppercase;letter-spacing:.05em}.table th:first-child,.table td:first-child{text-align:left}.table tr:last-child td{border-bottom:0}.muted{color:var(--muted)}.gear{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.gear-item{border:1px solid var(--line);background:var(--panel2);border-radius:8px;padding:10px}.gear-slot{font-size:11px;color:var(--muted)}.gear-level{font-size:16px;font-weight:700;margin-top:1px}.gear-id{font:11px Consolas,"Cascadia Mono",monospace;color:#9aa7b5;margin-top:3px}.set{display:inline-block;margin-top:6px;border-radius:5px;background:#403915;color:#f1dc77;padding:2px 6px;font-size:10px}.recap{border:1px solid var(--line);border-radius:8px;margin-bottom:9px;overflow:hidden}.recap-head{padding:8px 10px;background:#251b1d;color:#ffc0c0;font-weight:650}.event{display:grid;grid-template-columns:70px 72px minmax(0,1fr) 100px;gap:8px;padding:7px 9px;border-top:1px solid var(--line);font-size:12px}.heal{color:#8de0aa}.damage{color:#f0a0a0}.empty{padding:70px 20px;text-align:center;color:var(--muted)}.empty strong{display:block;color:#cdd6df;font-size:17px;margin-bottom:5px}.footer{padding:22px;text-align:center;color:#657180;font-size:11px}@media(max-width:980px){.shell{grid-template-columns:280px minmax(0,1fr)}.hero{grid-template-columns:repeat(3,1fr)}.layout{grid-template-columns:220px minmax(0,1fr)}}@media(max-width:720px){.shell{display:block}.left{position:relative;height:auto;max-height:380px;border-right:0;border-bottom:1px solid var(--line)}.enc-list{max-height:260px}.top{position:relative}.hero{grid-template-columns:repeat(2,1fr)}.layout{display:block}.players{margin-bottom:12px}.player-list{display:flex;overflow:auto}.player{min-width:170px}.gear{grid-template-columns:1fr}.content{padding:12px 10px 40px}.event{grid-template-columns:54px 60px minmax(0,1fr)}}
</style>
</head>
<body>
<div class="shell">
<aside class="left"><div class="brand"><h1>BPSR ReadyAlert</h1><p>Encounter History</p><div class="local">Offline / stored only on this PC</div></div><div class="search-wrap"><input id="search" class="search" type="search" autocomplete="off" placeholder="Search dungeon, boss or player…"></div><div id="enc-list" class="enc-list"></div></aside>
<main class="main"><div id="app"></div></main>
</div>
<script>const DATA="#;

const HTML_TAIL: &str = r#";
const $=s=>document.querySelector(s), list=$('#enc-list'), app=$('#app'), search=$('#search');
let filtered=DATA, selected=0, selectedPlayer=0, tab='overview';
const num=n=>(Number(n)||0).toLocaleString();
const compact=n=>{n=Number(n)||0;const a=Math.abs(n);if(a>=1e9)return (n/1e9).toFixed(a>=1e10?1:2)+'B';if(a>=1e6)return (n/1e6).toFixed(a>=1e7?1:2)+'M';if(a>=1e3)return (n/1e3).toFixed(a>=1e4?1:2)+'K';return num(n)};
const dur=ms=>{ms=Number(ms)||0;const s=Math.floor(ms/1000),m=Math.floor(s/60),r=s%60;return m?`${m}:${String(r).padStart(2,'0')}`:`${r}s`};
const pct=(a,b)=>b>0?`${(100*a/b).toFixed(1)}%`:'—';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const when=ms=>{const d=new Date(Number(ms)||0);return isNaN(d)?'Unknown time':d.toLocaleString()};
const scene=e=>e.context?.scene_name||e.target_name||`Scene ${e.context?.scene_id||'Unknown'}`;
const difficulty=e=>e.context?.difficulty||'';
const playLabel=n=>({2:'Dungeon',3:'Memory',5:'Race',6:'Event',8:'Unstable',9:'Dungeon',12:'Guild',13:'Guild Hunt',15:'World Boss',16:'Tower',17:'Master Dungeon',18:'Season Challenge',19:'Season Dungeon',20:'Event'}[n]||'Encounter');
const partName=p=>({200:'Weapon',201:'Head',202:'Chest',203:'Hands',204:'Boots',205:'Earring',206:'Necklace',207:'Ring',208:'Bracelet (L)',209:'Bracelet (R)',210:'Charm'}[p]||'Equipment');
function gearFor(e,row){const all=e.context?.player_gear||[];return all.find(g=>g.actor_uuid===row.actor_uuid)||all.find(g=>g.uid&&g.uid===row.uid)||{items:[]};}
function renderList(){list.innerHTML='';if(!filtered.length){list.innerHTML='<div class="empty"><strong>No encounters</strong>No saved encounter matches this search.</div>';return;}filtered.forEach((e,i)=>{const top=[...(e.snapshot?.rows||[])].sort((a,b)=>(b.damage||0)-(a.damage||0))[0];const b=document.createElement('button');b.className='enc-card'+(i===selected?' active':'');b.innerHTML=`<div class="enc-title">${esc(scene(e))}</div><div class="enc-meta"><span>${esc(when(e.ended_unix_ms))}</span>${difficulty(e)?`<span>• ${esc(difficulty(e))}</span>`:''}<span>• ${dur(e.snapshot?.encounter_ms)}</span></div><div class="enc-stat"><span>${(e.snapshot?.rows||[]).length} players</span><span>${compact(e.snapshot?.total_damage)} dmg${top?` · ${esc(top.name)}`:''}</span></div>`;b.onclick=()=>{selected=i;selectedPlayer=0;tab='overview';renderList();renderDetail()};list.appendChild(b)});}
function renderDetail(){const e=filtered[selected];if(!e){app.innerHTML='<div class="empty"><strong>No encounter selected</strong>Complete a combat encounter and it will appear here.</div>';return;}const s=e.snapshot||{},rows=[...(s.rows||[])].sort((a,b)=>(b.damage||0)-(a.damage||0));const target=s.target?.name||e.target_name||'Encounter';app.innerHTML=`<header class="top"><div class="title-row"><div><h2>${esc(scene(e))}</h2><div class="subtitle">${esc(target)} · ${esc(when(e.ended_unix_ms))}</div></div><div class="pills"><span class="pill">${esc(playLabel(e.context?.play_type))}</span>${difficulty(e)?`<span class="pill">${esc(difficulty(e))}</span>`:''}${e.context?.scene_id?`<span class="pill">Scene ${e.context.scene_id}</span>`:''}</div></div></header><div class="content"><section class="hero"><div class="metric"><div class="k">Duration</div><div class="v">${dur(s.encounter_ms)}</div></div><div class="metric"><div class="k">Damage</div><div class="v">${compact(s.total_damage)}</div></div><div class="metric"><div class="k">Healing</div><div class="v">${compact(s.total_healing)}</div></div><div class="metric"><div class="k">Damage taken</div><div class="v">${compact(s.total_damage_taken)}</div></div><div class="metric"><div class="k">Players</div><div class="v">${rows.length}</div></div></section><div class="layout"><section class="players"><div class="section-head">Players</div><div id="players" class="player-list"></div></section><section class="detail"><div class="tabs" id="tabs"></div><div class="pane" id="pane"></div></section></div><div class="footer">Saved locally by ReadyAlert · raw encounter files remain compressed in the EncounterHistory folder</div></div>`;const p=$('#players');rows.forEach((r,i)=>{const b=document.createElement('button');b.className='player'+(i===selectedPlayer?' active':'');b.innerHTML=`<div class="player-name">${esc(r.name||`Player ${r.uid||''}`)}</div><div class="player-sub">${esc(r.subprofession_name||'Unknown spec')} · ${compact(r.damage)} dmg · ${r.deaths||0} death${r.deaths===1?'':'s'}</div>`;b.onclick=()=>{selectedPlayer=i;renderPlayers(rows);renderPane(e,rows[selectedPlayer])};p.appendChild(b)});renderTabs();renderPane(e,rows[selectedPlayer]);}
function renderPlayers(rows){document.querySelectorAll('.player').forEach((b,i)=>b.classList.toggle('active',i===selectedPlayer));}
function renderTabs(){const tabs=[['overview','Overview'],['skills','Skills'],['gear','Gear'],['buffs','Buffs'],['deaths','Deaths'],['taken','Damage Taken']];const el=$('#tabs');el.innerHTML='';tabs.forEach(([id,label])=>{const b=document.createElement('button');b.className='tab'+(id===tab?' active':'');b.textContent=label;b.onclick=()=>{tab=id;renderTabs();const e=filtered[selected],rows=[...(e.snapshot?.rows||[])].sort((a,b)=>(b.damage||0)-(a.damage||0));renderPane(e,rows[selectedPlayer])};el.appendChild(b)});}
function renderPane(e,r){const pane=$('#pane');if(!r){pane.innerHTML='<div class="empty"><strong>No player rows</strong>This encounter did not contain player contribution data.</div>';return;}if(tab==='overview'){pane.innerHTML=`<div class="grid2"><div class="mini"><div class="label">Damage / DPS</div><div class="value">${compact(r.damage)} / ${compact(r.dps)}</div></div><div class="mini"><div class="label">Active DPS</div><div class="value">${compact(r.active_dps)}</div></div><div class="mini"><div class="label">Healing / effective</div><div class="value">${compact(r.healing)} / ${compact(r.effective_healing)}</div></div><div class="mini"><div class="label">Overhealing</div><div class="value">${compact(r.overhealing)}</div></div><div class="mini"><div class="label">Damage taken / absorbed</div><div class="value">${compact(r.damage_taken)} / ${compact(r.absorbed_damage)}</div></div><div class="mini"><div class="label">Hits · Crit · Lucky</div><div class="value">${num(r.hits)} · ${pct(r.crits,r.hits)} · ${pct(r.lucky_hits,r.hits)}</div></div><div class="mini"><div class="label">Boss damage</div><div class="value">${compact(r.boss_damage)} <span class="muted">(${pct(r.boss_damage,r.damage)})</span></div></div><div class="mini"><div class="label">Deaths</div><div class="value">${num(r.deaths)}</div></div></div>`;return;}if(tab==='skills'){const skills=[...(r.skills||[])].sort((a,b)=>(b.damage+b.healing)-(a.damage+a.healing));pane.innerHTML=skills.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Skill</th><th>Damage</th><th>Boss</th><th>Healing</th><th>Hits</th><th>Crit</th><th>Lucky</th><th>Min</th><th>Max</th></tr></thead><tbody>${skills.map(x=>`<tr><td>${esc(x.name||`Skill ${x.skill_id}`)}</td><td>${compact(x.damage)}</td><td>${compact(x.boss_damage)}</td><td>${compact(x.healing)}</td><td>${num(x.hits)}</td><td>${pct(x.crits,x.hits)}</td><td>${pct(x.lucky_hits,x.hits)}</td><td>${x.min_value?compact(x.min_value):'—'}</td><td>${x.max_value?compact(x.max_value):'—'}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty"><strong>No skill breakdown</strong>No outgoing skill events were retained for this player.</div>';return;}if(tab==='gear'){const items=gearFor(e,r).items||[];const sets={};for(const x of items)if(x.suit_id>0)sets[x.suit_id]=(sets[x.suit_id]||0)+1;pane.innerHTML=items.length?`<div class="gear">${items.map(x=>`<div class="gear-item"><div class="gear-slot">${esc(partName(x.part))}</div><div class="gear-level">${x.gear_level?`Lv.${x.gear_level}`:'Observed gear'}</div><div class="gear-id">Item ${x.equip_id}${x.slot?` · slot ${x.slot}`:''}</div>${x.suit_id?`<span class="set">Set ${x.suit_id} · ${sets[x.suit_id]} piece${sets[x.suit_id]===1?'':'s'}</span>`:''}</div>`).join('')}</div><p class="muted" style="margin:12px 2px 0;font-size:11px">Gear shows packet-observed equipment ID, table gear level and SuitId only. ReadyAlert does not invent Breakthrough or Reforge values that were not transmitted.</p>`:'<div class="empty"><strong>Gear not observed</strong>The game did not synchronize equipment data for this player during the saved encounter.</div>';return;}if(tab==='buffs'){const buffs=[...(r.buff_uptimes||[])].sort((a,b)=>(b.uptime_ms||0)-(a.uptime_ms||0));pane.innerHTML=buffs.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Buff</th><th>Uptime</th><th>Time</th><th>Activations</th></tr></thead><tbody>${buffs.map(x=>`<tr><td>${esc(x.name||`Buff ${x.buff_id}`)}</td><td>${pct(x.uptime_ms,e.snapshot.encounter_ms)}</td><td>${dur(x.uptime_ms)}</td><td>${num(x.activations)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty"><strong>No named buff uptime</strong>No supported buff uptime data was retained for this player.</div>';return;}if(tab==='deaths'){const recaps=r.death_recaps||[];pane.innerHTML=recaps.length?recaps.map(d=>`<div class="recap"><div class="recap-head">Death ${d.death_no} · ${dur(d.at_ms)} into encounter</div>${(d.events||[]).map(x=>`<div class="event"><span>${dur(x.at_ms)}</span><span class="${x.is_heal?'heal':'damage'}">${x.is_heal?'HEAL':'HIT'}</span><span>${esc(x.source_name||'Unknown')} · ${esc(x.skill_name||`Skill ${x.skill_id}`)}</span><strong>${compact(x.value)}</strong></div>`).join('')}</div>`).join(''):'<div class="empty"><strong>No death recap</strong>This player had no recorded deaths in the encounter.</div>';return;}if(tab==='taken'){const src=[...(r.taken_sources||[])].sort((a,b)=>(b.damage||0)-(a.damage||0)),abs=[...(r.absorbed_sources||[])].sort((a,b)=>(b.damage||0)-(a.damage||0));const table=(rows,label)=>rows.length?`<div class="section-head" style="margin:10px 0 6px;padding-left:0;border:0">${label}</div><div class="table-wrap"><table class="table"><thead><tr><th>Source / skill</th><th>Amount</th><th>Hits</th><th>Crit</th><th>Lucky</th><th>Max</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x.source_name||'Unknown')} · ${esc(x.skill_name||`Skill ${x.skill_id}`)}</td><td>${compact(x.damage)}</td><td>${num(x.hits)}</td><td>${pct(x.crits,x.hits)}</td><td>${pct(x.lucky_hits,x.hits)}</td><td>${compact(x.max_value)}</td></tr>`).join('')}</tbody></table></div>`:'';pane.innerHTML=(table(src,'HP damage taken')+table(abs,'Direct absorbed / shield events'))||'<div class="empty"><strong>No incoming breakdown</strong>No supported incoming damage sources were retained.</div>';}}
function applySearch(){const q=(search.value||'').trim().toLocaleLowerCase();filtered=DATA.filter(e=>{if(!q)return true;const rows=e.snapshot?.rows||[];return [scene(e),e.target_name,e.context?.difficulty,...rows.map(r=>r.name),...rows.map(r=>r.subprofession_name)].join(' ').toLocaleLowerCase().includes(q)});selected=0;selectedPlayer=0;tab='overview';renderList();renderDetail();}
search.addEventListener('input',applySearch);document.addEventListener('keydown',ev=>{if(ev.key==='/'&&document.activeElement!==search){ev.preventDefault();search.focus()}else if(ev.key==='Escape'&&search.value){search.value='';applySearch();search.focus()}});renderList();renderDetail();
</script>
</body></html>
"#;

#[cfg(test)]
mod tests {
    use super::*;
    use crate::{encounter_context::EncounterContextSnapshot, encounter_store, model::{DpsRow, DpsSnapshot}};
    use std::time::{SystemTime, UNIX_EPOCH};

    #[test]
    fn generates_offline_html_with_saved_encounter() {
        let nonce = SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_nanos();
        let root = std::env::temp_dir().join(format!("readyalert-encounter-html-{}-{nonce}", std::process::id()));
        let snapshot = DpsSnapshot { encounter_ms: 1_000, total_damage: 12_345, rows: vec![DpsRow { uid: 1, name: "Alice".into(), damage: 12_345, ..Default::default() }], ..Default::default() };
        let context = EncounterContextSnapshot { scene_id: 1151, scene_name: "Void - Towering Ruin".into(), ..Default::default() };
        encounter_store::archive(&root, &snapshot, &context, 10).unwrap();
        let path = generate(&root).unwrap();
        let html = fs::read_to_string(path).unwrap();
        assert!(html.contains("Encounter History"));
        assert!(html.contains("Void - Towering Ruin"));
        assert!(html.contains("Alice"));
        let _ = fs::remove_dir_all(root);
    }
}
